  "faq_1_a": "ಹೌದು. CCTVQuotation ನ ಪ್ರತಿ ಕೊಟೇಶನ್‌ನಲ್ಲೂ 18% GST ಸೇರಿದೆ — ಯಾವುದೇ ಗುಪ್ತ ಶುಲ್ಕವಿಲ್ಲ. ಇದರಲ್ಲಿ ಕ್ಯಾಮೆರಾ, DVR/NVR, ಕೇಬಲ್ ಮತ್ತು ಪೂರ್ತಿ ಫಿಟ್ಟಿಂಗ್ ಎಲ್ಲವೂ ಸೇರಿರುತ್ತದೆ.",
