  "faq_3_a": "ಪೂರ್ತಿ 4-ಕ್ಯಾಮೆರಾ ಸೆಟಪ್ ಬ್ರ್ಯಾಂಡ್ ಮತ್ತು ಫೀಚರ್‌ಗಳ ಪ್ರಕಾರ ಸುಮಾರು ₹14,200 ರಿಂದ ₹18,000 ದಿಂದ ಶುರುವಾಗುತ್ತದೆ. ಎಲ್ಲಾ ದರಗಳಲ್ಲೂ 18% GST, ಕೇಬಲ್ ಮತ್ತು ಫಿಟ್ಟಿಂಗ್ ಸೇರಿದೆ.",
